CREATE VIRTUAL TABLE fts USING fts3(content TEXT); INSERT INTO fts(rowid,content) VALUES(1,'this is a test of the fts3 virtual'),(2,'table used as part of a join together'),(3,'with the DISTINCT keyword.  There was'),(4,'a bug at one time (2013-06 through 2014-04)'),(5,'that prevented this from working correctly.'),(11,'a row that occurs twice'),(12,'a row that occurs twice'); CREATE TABLE t1(x TEXT PRIMARY KEY, y); INSERT OR IGNORE INTO t1 SELECT content, rowid+100 FROM fts;